verify.cmd:
node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs=require("fs"),cp=require("child_process")
const fail=(m)=>{console.error(m);process.exit(1)}
if(!fs.existsSync("scripts/load-soak.mjs"))fail("there is no load or soak harness: scripts/load-soak.mjs does not exist, so every H3 scale claim is still unprovable")
const r=cp.spawnSync(process.execPath,["scripts/load-soak.mjs","--smoke","--json"],{encoding:"utf8",timeout:60000})
if(r.error||r.signal)process.exit(79)
if(r.status!==0)fail("the harness smoke run failed (exit "+r.status+"): "+(r.stderr||"").trim().split("\n").pop())
let rep;try{rep=JSON.parse(r.stdout)}catch(e){fail("the smoke run printed no machine-readable report")}
Promise.all([import("@/lib/observability/slos.ts"),import("./scripts/load-soak.mjs")]).then(([m,h])=>{
if(!rep.slos||rep.slos.source!=="lib/observability/slos.ts")fail("the report does not say it judged against lib/observability/slos.ts")
const slo=(id)=>m.SLOS.find((s)=>s.id===id)
for(const id of ["latency.read-hot-paths","latency.practice-log-write","error-rate.requests"]){const got=(rep.slos.read||[]).find((x)=>x.id===id);if(!slo(id)||!got||got.target!==slo(id).target)fail("the report does not carry "+id+" as slos.ts states it, so it is not reading the SLO table")}
const want={"feed":"latency.read-hot-paths","circle-detail":"latency.read-hot-paths","people-directory":"latency.read-hot-paths","events-catalog":"latency.read-hot-paths","practice-log-write":"latency.practice-log-write"}
const paths=(rep.phases&&rep.phases[0]&&rep.phases[0].paths)||[]
for(const [id,sid] of Object.entries(want)){const p=paths.find((x)=>x.id===id);if(!p||!(p.requests>0)||typeof p.p95!=="number"||typeof p.errorRatePct!=="number"||p.verdict!=="pass")fail("hot path "+id+" was not driven and measured (requests, p95, error rate, verdict) in smoke mode");if(!p.slo||p.slo.id!==sid||p.slo.target!==slo(sid).target)fail("hot path "+id+" is not judged against "+sid+" from slos.ts")}
if(rep.target.hostKind!=="local"||rep.target.env!=="mock")fail("smoke mode did not run against the local mock")
for(const u of ["https://frequencylocal.com","https://www.frequencylocal.com"]){if(h.preflightTarget(u).ok)fail("the harness would load production ("+u+") without --allow-production")}
if(h.guardBuildEnv({hostKind:"preview",statusEnv:"production"}).ok)fail("the harness would load a build that reports build.env production")
console.log("ok")
}).catch((e)=>fail("cannot import the harness or slos.ts: "+(e&&e.message)))'
